ON CONFLICT(id) DO UPDATE SET content_key=excluded.content_key,stage=excluded.stage,topic=excluded.topic,en=excluded.en,ko=excluded.ko,example=excluded.example,translation=excluded.translation,example_2=excluded.example_2,translation_2=excluded.translation_2,status=excluded.status,updated_at=now();
UPDATE ovh.content_versions SET snapshot=ovh.content_snapshot() WHERE version='2026.11.10.1';
